const s = $('Simulator Settings').first().json;
const fromForm = $('Choose Customer Scenario').isExecuted;
const KEYS = { 'Form filler': 'form_filler', 'Cart abandoner': 'cart_abandoner', 'Buyer': 'buyer', 'Repeat buyer': 'repeat_buyer', 'Dormant customer': 'dormant' };
const stamp = Date.now();
const base = { first_name: 'Maria', last_name: 'Rossi', email: 'demo-customer@example.test', phone: '+15550100', message: 'Hi, is the blue jacket available in size M?', cart_items: 'Blue jacket', cart_total: 89, previous_orders: 1, days_since_last_order: 61 };
// Real store product: the first product in the Shopify store gives the cart item and price (falls back to the values above).
const product = $('Read Products (Shopify)').first().json || {};
if (product.title) { base.cart_items = product.title; base.cart_total = Number(((product.variants || [])[0] || {}).price) || base.cart_total; }
let runs;
if (fromForm) {
  const f = $('Choose Customer Scenario').first().json;
  runs = [{ scenario: KEYS[f['Scenario']] || 'form_filler', first_name: f['First name'] || base.first_name, last_name: f['Last name'] || base.last_name, email: String(f['Email'] || base.email).toLowerCase(), phone: f['Phone'] === undefined ? base.phone : String(f['Phone']).trim(), message: f['Message'] || base.message, cart_items: f['Cart items'] || base.cart_items, cart_total: Number(f['Cart total'] ?? base.cart_total), previous_orders: Number(f['Previous orders'] ?? base.previous_orders), days_since_last_order: Number(f['Days since last order'] ?? base.days_since_last_order) }];
} else {
  runs = Object.values(KEYS).map(k => ({ ...base, scenario: k, email: 'demo+' + k + '-' + stamp + '@example.test' }));
}
const FAKE_PHONE = '+15550100'; // NANP's reserved fictional-number block (555-0100-0199) - treat it as no real phone so the demo exercises the email fallback instead of a fake SMS
runs = runs.map(r => ({ ...r, phone: r.phone === FAKE_PHONE ? '' : r.phone }));
const events = [];
let idx = 0;
for (const r of runs) {
  const runId = 'sim-' + stamp + '-' + idx++;
  const startedAt = new Date().toISOString();
  const ck = 'ck-' + runId;
  const customer = orders => ({ first_name: r.first_name, last_name: r.last_name, email: r.email, orders_count: orders });
  const push = ev => events.push({ run_id: runId, started_at: startedAt, scenario: r.scenario, email: r.email, phone: r.phone, first_name: r.first_name, days_since_last_order: r.days_since_last_order, intake_url: s.intake_url, ...ev });
  const hdr = topic => ({ 'x-shopify-topic': topic, 'x-demo-run-id': runId });
  const checkout = { token: ck, email: r.email, phone: r.phone, customer: customer(0), abandoned_checkout_url: 'https://your-store.example/checkouts/' + ck, line_items: [{ title: r.cart_items, quantity: 1 }], total_price: String(r.cart_total) };
  const order = orders => ({ id: 'ord-' + runId, email: r.email, customer: customer(orders), total_price: String(r.cart_total), checkout_token: ck });
  if (r.scenario === 'form_filler') {
    push({ topic: '', headers_obj: { 'x-demo-run-id': runId }, raw_body: JSON.stringify({ event_type: 'contact_form', first_name: r.first_name, last_name: r.last_name, email: r.email, phone: r.phone, message: r.message, run_id: runId }) });
  } else if (r.scenario === 'cart_abandoner') {
    push({ topic: 'checkouts/create', headers_obj: hdr('checkouts/create'), raw_body: JSON.stringify(checkout) });
  } else if (r.scenario === 'buyer') {
    push({ topic: 'checkouts/create', headers_obj: hdr('checkouts/create'), raw_body: JSON.stringify(checkout) });
    push({ topic: 'orders/paid', headers_obj: hdr('orders/paid'), raw_body: JSON.stringify(order(1)) });
  } else if (r.scenario === 'repeat_buyer') {
    push({ topic: 'orders/paid', headers_obj: hdr('orders/paid'), raw_body: JSON.stringify(order(r.previous_orders + 1)) });
  } else if (r.scenario === 'dormant') {
    push({ needs_seed: true, seed_last_order_date: new Date(Date.now() - r.days_since_last_order * 86400000).toISOString(), seed_first_name: r.first_name, seed_last_name: r.last_name, topic: '', headers_obj: { 'x-demo-run-id': runId, 'x-admin-token': s.admin_token }, raw_body: JSON.stringify({ event_type: 'winback_run', run_id: runId }) });
  }
}
return events.map(e => ({ json: e }));

const seen = new Map();
for (const it of $('Prepare Scenario Runs').all()) {
  const j = it.json;
  if (!seen.has(j.run_id)) seen.set(j.run_id, { run_id: j.run_id, scenario: j.scenario, email: j.email, phone: j.phone, days_since_last_order: j.days_since_last_order, started_at: j.started_at });
}
return [...seen.values()].map(j => ({ json: j }));

const runs = $('Collect Scenario Runs').all().map(i => i.json);
const mail = $('Read Mailpit Messages (Mailpit API)').all().map(i => i.json);
// Real email: what the Gmail account sent in the last hour (the server sends through Gmail, the local test copy through Mailpit).
const sentMail = $('Read Sent Gmail Messages (Gmail)').all().map(i => i.json || {}).filter(m => m.id);
const logRows = $('Read Mock Log Rows').all().map(i => i.json).filter(r => r && r.email);
// Live mode: the real GoHighLevel contact, opportunity and notes, one item per run (same order as the runs).
const ghlContacts = $('Read GHL Contact (GHL API)').all().map(i => ((i.json || {}).contacts || [])[0] || {});
const ghlOpps = $('Read GHL Opportunity (GHL API)').all().map(i => i.json || {});
const ghlNotes = $('Read GHL Contact Notes (GHL API)').all().map(i => i.json || {});
const STAGE_KEY = { 'New Lead': 'new_lead', 'Contacted': 'contacted', 'Cart Created': 'cart_created', 'Purchased': 'purchased', 'Repeat Customer': 'repeat_customer' };
const RANK = { new_lead: 1, contacted: 2, cart_created: 3, purchased: 4, repeat_customer: 5 };
const stageName = {};
(($('Read GHL Pipelines (GHL API)').first().json || {}).pipelines || []).forEach(p => (p.stages || []).forEach(st => { stageName[st.id] = st.name; }));
const results = runs.map((run, i) => {
  const started = new Date(run.started_at).getTime() - 2000;
  const subjects = ((mail[i] && mail[i].messages) || []).filter(m => new Date(m.Created).getTime() >= started).map(m => m.Subject || '')
    .concat(sentMail.filter(m => String(m.To || '').toLowerCase().includes(run.email) && Number(m.internalDate || 0) >= started).map(m => m.Subject || ''));
  const rows = logRows.filter(r => r.email === run.email && new Date(r.ts).getTime() >= started);
  const stageRows = rows.filter(r => r.kind === 'stage').map(r => { try { return JSON.parse(r.detail); } catch (e) { return {}; } });
  const gc = ghlContacts[i] || {};
  const live = !!gc.id && String(gc.email || '').toLowerCase() === run.email;
  const opp = (((ghlOpps[i] || {}).opportunities) || [])[0] || {};
  const liveStage = STAGE_KEY[stageName[opp.pipelineStageId]] || '';
  const liveTags = (gc.tags || []).map(t => String(t).toLowerCase());
  const smsTexts = live ? (((ghlNotes[i] || {}).notes) || []).map(n => n.body || '').filter(b => b.startsWith('SMS')) : rows.filter(r => r.kind === 'sms').map(r => r.detail || '');
  // Live: GoHighLevel shows only the final stage, so a target counts when the contact reached it or a later stage.
  const hasTarget = t => live ? (RANK[liveStage] || 0) >= (RANK[t] || 99) : stageRows.some(d => d.target_stage === t);
  const hasTag = t => live ? liveTags.includes(t.toLowerCase()) : stageRows.some(d => (d.tags || []).includes(t));
  const subjectStarts = s => subjects.some(x => x.startsWith(s));
  const hasPhone = !!run.phone;
  const checks = [];
  const check = (name, ok, detail) => checks.push({ name, ok: !!ok, detail: detail || '' });
  if (run.scenario === 'form_filler') {
    check('Contact created as New Lead with tag source:contact-form', hasTarget('new_lead') && hasTag('source:contact-form'));
    check('Auto-reply email sent (Mailpit or Gmail)', subjectStarts('Thanks for reaching out'), subjects.join(' | '));
    check(hasPhone ? 'Reply SMS recorded' : 'No SMS (no phone number)', hasPhone ? smsTexts.some(t => t.includes('thanks for reaching out')) : smsTexts.length === 0, smsTexts.join(' | '));
    check('Contact moved to Contacted', hasTarget('contacted'));
  } else if (run.scenario === 'cart_abandoner') {
    check('Contact set to Cart Created with tag cart-open', hasTarget('cart_created') && hasTag('cart-open'));
    check(hasPhone ? 'Reminder SMS recorded' : 'Reminder email received', hasPhone ? smsTexts.some(t => t.includes('left')) : subjectStarts('You left something'), hasPhone ? smsTexts.join(' | ') : subjects.join(' | '));
    check('Contact tagged cart-reminder-sent', hasTag('cart-reminder-sent'));
  } else if (run.scenario === 'buyer') {
    check('Contact moved to Purchased (or Repeat Customer if seen before)', hasTarget('purchased') || hasTarget('repeat_customer'));
    check('No cart reminder sent', smsTexts.length === 0 && !subjectStarts('You left something'), smsTexts.concat(subjects).join(' | '));
  } else if (run.scenario === 'repeat_buyer') {
    check('Contact moved to Repeat Customer', hasTarget('repeat_customer'));
  } else if (run.scenario === 'dormant') {
    const due = Number(run.days_since_last_order) >= 60;
    check(due ? 'Win-back email received' : 'No win-back email (last order not old enough)', due ? subjectStarts('We miss you') : !subjectStarts('We miss you'), subjects.join(' | '));
    check(due ? 'Contact tagged winback-active' : 'Contact not tagged winback-active', due ? hasTag('winback-active') : !hasTag('winback-active'));
  }
  return { scenario: run.scenario, email: run.email, mode: live ? 'live' : 'mock', ghl_contact_id: live ? gc.id : '', ghl_opportunity_id: live ? (opp.id || '') : '', pass: checks.every(c => c.ok), checks };
});
return results.map(r => ({ json: r }));

const rows = $('Assert Scenario Outcomes').all().map(i => i.json);
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;');
const html = '<table style="border-collapse:collapse;width:100%">' + rows.map(r => '<tr><td style="padding:6px;border:1px solid #ccc;vertical-align:top"><b>' + esc(r.scenario) + '</b><br>' + esc(r.email) + '</td><td style="padding:6px;border:1px solid #ccc"><b style="color:' + (r.pass ? 'green' : 'red') + '">' + (r.pass ? 'PASS' : 'FAIL') + '</b><br>' + r.checks.map(c => (c.ok ? '&#10003; ' : '&#10007; ') + esc(c.name) + (c.ok || !c.detail ? '' : ' <i>(' + esc(c.detail) + ')</i>')).join('<br>') + '</td></tr>').join('') + '</table>';
return [{ json: { all_pass: rows.every(r => r.pass), summary: rows.map(r => r.scenario + ' (' + r.mode + '): ' + (r.pass ? 'PASS' : 'FAIL')).join(', '), html } }];
